import{_ as s,o as a,c as i,au as t}from"./chunks/framework.BTTEhLNX.js";const k=JSON.parse('{"title":"Building Krawler jobs","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"building-jobs.md","filePath":"building-jobs.md"}'),l={name:"building-jobs.md"};function o(r,e,n,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="building-krawler-jobs" tabindex="-1">Building Krawler jobs <a class="header-anchor" href="#building-krawler-jobs" aria-label="Permalink to &quot;Building Krawler jobs&quot;">​</a></h1><p>This document describes how Krawler job images are built and released in <strong>krawler-ekosystem</strong>, and how the framework (<code>@kalisio/krawler</code>) relates to the jobs at build time.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>Each job package in <code>packages/krawler-&lt;job&gt;/</code> ships its own Docker image, derived from the published Krawler image via a two-stage build:</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> kalisio/krawler:\${KRAWLER_TAG}</span></span></code></pre></div><p>The <code>KRAWLER_TAG</code> is <strong>the single point that decides which Krawler version a job runs on</strong>. It is resolved at <code>docker build</code> time from:</p><ol><li>an explicit <code>KRAWLER_TAG</code> env var if set (used by CI on master to force <code>latest</code>), or</li><li>the <code>krawler.version</code> field in the job&#39;s <code>package.json</code> otherwise (used on release tags).</li></ol><p>The job&#39;s npm <code>build</code> script wires this:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DOCKER_BUILDKIT=1 docker build --build-arg KRAWLER_TAG=\${KRAWLER_TAG:-$(node -p </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">require(&#39;./package.json&#39;).krawler.version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)} ...&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The <code>peerDependencies[&quot;@kalisio/krawler&quot;]</code> entry in a job&#39;s <code>package.json</code> only exists for pnpm workspace symlink resolution. <strong>It does not drive the build version</strong> — only <code>krawler.version</code> does.</p></div><h2 id="master-vs-tag" tabindex="-1">Master vs tag <a class="header-anchor" href="#master-vs-tag" aria-label="Permalink to &quot;Master vs tag&quot;">​</a></h2><p>Krawler and the jobs have independent release cycles. The CI distinguishes two flows:</p><table tabindex="0"><thead><tr><th>Event</th><th>CI action</th><th>Image produced</th><th>Krawler base</th></tr></thead><tbody><tr><td>Push on <code>master</code> (Krawler, unless <code>skip krawler</code> in commit msg)</td><td>build Krawler</td><td><code>kalisio/krawler:dev</code></td><td>n/a</td></tr><tr><td>Push on <code>master</code> (job, with <code>build jobs</code> in commit msg)</td><td>build the job (all variants)</td><td><code>&lt;job&gt;:dev</code></td><td><code>kalisio/krawler:latest</code></td></tr><tr><td>Tag <code>@kalisio/krawler@X.Y.Z</code></td><td>release Krawler</td><td><code>kalisio/krawler:X.Y.Z</code></td><td>n/a</td></tr><tr><td>Tag <code>@kalisio/krawler-&lt;job&gt;@X.Y.Z</code></td><td>release the job (all variants)</td><td><code>&lt;job&gt;:X.Y.Z</code></td><td><code>kalisio/krawler:&lt;package.json.krawler.version&gt;</code></td></tr></tbody></table><p>Design rationale:</p><ul><li><strong>Master Krawler does not cascade to jobs.</strong> A broken Krawler in master must not silently break every <code>&lt;job&gt;:dev</code>. Jobs pick up new Krawler lazily, on their next own build, and only based on the <strong>last released</strong> Krawler (<code>:latest</code>), not on the bleeding-edge <code>:dev</code>.</li><li><strong><code>&lt;job&gt;:dev</code> rebases on <code>krawler:latest</code>.</strong> <code>:latest</code> is stable (last release), so a broken Krawler in master never poisons <code>&lt;job&gt;:dev</code>. Jobs publish under <code>:dev</code> to make it obvious which images come from a master build vs a release.</li><li><strong><code>&lt;job&gt;:X.Y.Z</code> pins on <code>krawler.version</code>.</strong> Releases must be reproducible — six months later, the same tag must produce the same image.</li><li><strong>Jobs always build <code>FROM kalisio/krawler:&lt;tag&gt;</code>, never from sources.</strong> Consistent with out-of-monorepo jobs which don&#39;t have access to Krawler sources.</li></ul><h2 id="release-flow-changesets" tabindex="-1">Release flow (Changesets) <a class="header-anchor" href="#release-flow-changesets" aria-label="Permalink to &quot;Release flow (Changesets)&quot;">​</a></h2><p>Releases are driven by <a href="https://github.com/changesets/changesets" target="_blank" rel="noreferrer">Changesets</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. record intent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changeset</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. apply version bumps to package.json + CHANGELOG.md</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changeset:version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. publish to npm and create git tags</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changeset:publish</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. push the tags</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --follow-tags</span></span></code></pre></div><p>Step 4 triggers the CI release path:</p><ul><li>A tag matching <code>@kalisio/krawler@X.Y.Z</code> runs <code>release_krawler</code> → builds and pushes <code>kalisio/krawler:X.Y.Z</code> on DockerHub.</li><li>A tag matching <code>@kalisio/krawler-&lt;job&gt;@X.Y.Z</code> runs <code>release_jobs</code> → builds and pushes <code>&lt;job&gt;:X.Y.Z</code> (one image per variant).</li></ul><p>The release detector (<code>scripts/detect_release.sh</code>) cross-checks the tag version against <code>package.json.version</code> and fails the CI if they diverge.</p><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p><code>.changeset/config.json</code> is set to <code>&quot;updateInternalDependencies&quot;: false</code>. This means a Krawler bump <strong>does not</strong> generate automatic patches on the jobs. Jobs upgrade Krawler <strong>explicitly</strong> by bumping <code>krawler.version</code>.</p><h2 id="upgrading-a-job-s-krawler-base" tabindex="-1">Upgrading a job&#39;s Krawler base <a class="header-anchor" href="#upgrading-a-job-s-krawler-base" aria-label="Permalink to &quot;Upgrading a job&#39;s Krawler base&quot;">​</a></h2><p>Currently a manual edit:</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// packages/krawler-&lt;job&gt;/package.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;krawler&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.9.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Bump the field, commit, and the next release of that job (whether <code>:latest</code> on master push or <code>:X.Y.Z</code> on tag push) will rebase on the new Krawler version.</p><h2 id="manual-builds" tabindex="-1">Manual builds <a class="header-anchor" href="#manual-builds" aria-label="Permalink to &quot;Manual builds&quot;">​</a></h2><p>Outside of CI you can drive a build with the same wrapper:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Use whatever Krawler base + image tag you want</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KRAWLER_TAG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2.8.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TAG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2.8.2</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/krawler-openradiation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build a single variant</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KRAWLER_TAG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">latest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TAG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">latest</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/krawler-meteofrance</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:arome-france</span></span></code></pre></div><p><code>TAG</code> overrides the local image tag; <code>KRAWLER_TAG</code> overrides the Krawler base. Both env vars are honored by the job&#39;s <code>build</code> script.</p><h2 id="ci-internals" tabindex="-1">CI internals <a class="header-anchor" href="#ci-internals" aria-label="Permalink to &quot;CI internals&quot;">​</a></h2><ul><li><a href="https://github.com/kalisio/krawler-ekosystem/blob/master/scripts/detect_jobs.sh" target="_blank" rel="noreferrer"><code>scripts/detect_jobs.sh</code></a> — master path: detects which jobs to rebuild from a git diff. Includes a cascade list (lockfile, build scripts) that triggers all jobs when modified.</li><li><a href="https://github.com/kalisio/krawler-ekosystem/blob/master/scripts/detect_release.sh" target="_blank" rel="noreferrer"><code>scripts/detect_release.sh</code></a> — tag path: parses <code>GITHUB_REF_NAME</code>, resolves the target package, and emits the per-variant build matrix.</li><li><a href="https://github.com/kalisio/krawler-ekosystem/blob/master/scripts/build_krawler.sh" target="_blank" rel="noreferrer"><code>scripts/build_krawler.sh</code></a> — builds the Krawler framework image. Called by the <code>build_krawler</code> job on master push (pushes <code>:dev</code>) and by <code>release_krawler</code> on tag (pushes <code>:X.Y.Z</code>). Defaults <code>KRAWLER_TAG=&quot;dev&quot;</code> outside of a tag.</li><li><a href="https://github.com/kalisio/krawler-ekosystem/blob/master/scripts/build_krawler_job.sh" target="_blank" rel="noreferrer"><code>scripts/build_krawler_job.sh</code></a> — builds a single job image. Outside of a tag, exports <code>KRAWLER_TAG=latest</code> (so the job rebases on the last released <code>kalisio/krawler:latest</code>, not on the bleeding-edge <code>:dev</code>) and <code>JOB_DEFAULT_TAG=dev</code> (so the job image itself is published as <code>&lt;job&gt;:dev</code>). On tag, leaves both unset so the job&#39;s <code>krawler.version</code> wins for the base and <code>$VERSION</code> for the image tag.</li><li><a href="https://github.com/kalisio/krawler-ekosystem/blob/master/.github/workflows/main.yaml" target="_blank" rel="noreferrer"><code>.github/workflows/main.yaml</code></a> — orchestration. Master-path jobs are gated on <code>ref_type == &#39;branch&#39;</code>; release-path jobs trigger on tags matching <code>&#39;@*/*@*&#39;</code>.</li></ul>`,33)])])}const g=s(l,[["render",o]]);export{k as __pageData,g as default};
